  const html = template
    .replace('<title id="page-title">Blog - KwordSEO</title>', '<title id="page-title">' + esc(post.title) + ' - KwordSEO</title>')
    .replace('<meta id="meta-desc" name="description" content="">', '<meta id="meta-desc" name="description" content="' + esc(post.desc) + '">')
    .replace('<link rel="canonical" id="canonical-link" href="">', '<link rel="canonical" id="canonical-link" href="' + postUrl + '">')
    .replace('<link rel="alternate" hreflang="en" href="">', '<link rel="alternate" hreflang="en" href="' + postUrl + '">')
    .replace('<link rel="alternate" hreflang="en-US" href="">', '<link rel="alternate" hreflang="en-US" href="' + postUrl + '">')
    .replace('<link rel="alternate" hreflang="en-GB" href="">', '<link rel="alternate" hreflang="en-GB" href="' + postUrl + '">')
    .replace('<link rel="alternate" hreflang="x-default" href="">', '<link rel="alternate" hreflang="x-default" href="' + postUrl + '">')
